fn main() {
    let data = 42;
    let r1: &i32 = &data;
    let r2: &i32 = &data;
    // This code compiles and runs successfully because we only have immutable borrows.
    // Attempting to create a mutable borrow here would fail due to Rust's borrowing rules.
    assert_eq!(*r1, 42);
    assert_eq!(*r2, 42);
    println!("success");
}
